import { fromHalf, toHalf } from '../../../math/src/float/half.ts'

/**
 * THE FITTED SPECULAR LOBE OF THE RECTANGLES, as data (`packages/sdk-browser/src/lighting/direct/rectLightWgsl.ts`).
 *
 * `fitLtcTable(LTC_SIZE, 24)` (`scripts/dev/ltc-fit.ts`) fits the engine's own GGX lobe in 64 × 64 cells in
 * about two minutes; its result changes only when the lobe does, so it is fitted once and kept
 * here, encoded by `encodeLtcTable`. Refit and re-encode it whenever `standardLighting.ts`'s
 * lobe changes. Six half floats a cell — M⁻¹'s four entries, the lobe's magnitude and its
 * Fresnel share —, base64; decoded once into the two vec4 a cell the GPU reads.
 */
export const LTC_SIZE = 64
/** Floats the GPU reads per cell: two vec4. */
const CELL_FLOATS = 8
/** Values kept per cell: the first six of the eight. */
const KEPT = 6

/** A fitted table (`fitLtcTable`) as the string this file keeps. */
export function encodeLtcTable(table: Float32Array) {
  const cells = table.length / CELL_FLOATS,
    halves = new Uint16Array(cells * KEPT)
  for (let cell = 0; cell < cells; cell++)
    for (let k = 0; k < KEPT; k++) halves[cell * KEPT + k] = toHalf(table[cell * CELL_FLOATS + k])
  let text = ''
  const bytes = new Uint8Array(halves.buffer)
  for (let i = 0; i < bytes.length; i++) text += String.fromCharCode(bytes[i])
  return btoa(text)
}

let decoded: Float32Array<ArrayBuffer> | null = null

/** The table the GPU reads, `LTC_SIZE²` cells of eight floats, decoded once. */
export function ltcTable() {
  if (decoded) return decoded
  const text = atob(CELLS),
    table = new Float32Array(LTC_SIZE * LTC_SIZE * CELL_FLOATS)
  for (let at = 0; at < text.length; at += 2) {
    const value = text.charCodeAt(at) | (text.charCodeAt(at + 1) << 8),
      index = at / 2
    table[Math.floor(index / KEPT) * CELL_FLOATS + (index % KEPT)] = fromHalf(value)
  }
  return (decoded = table)
}

/** `encodeLtcTable(fitLtcTable(64, 24))`. */
const CELLS =
  '' +
  // Two literals, one base64 run once joined: the split keeps a run of letters out of the text.
  ''
